# A pending critical import suppresses any new chart read. The import completion itself
# enqueues a fresh CRITICAL generation, so no display request is lost.
replace_once(
    main,
    '''            .collect {\n                val priorityRank = reloadPendingPriority\n                reloadPendingPriority = 0\n                reloadMutex.withLock {\n''',
    '''            .collect {\n                val priorityRank = reloadPendingPriority\n                reloadPendingPriority = 0\n                if (FabDataWorkArbiter.criticalImportPending()) {\n                    reloadPendingPriority = maxOf(reloadPendingPriority, priorityRank)\n                    return@collect\n                }\n                reloadMutex.withLock {\n''',
)
